// Schedule channel IDs used to identify which thread yielded or runs next

pub const pad: u32 = 0;

pub const operator_interface_oip_oit_MON: u32 = 2;

pub const temperature_sensor_cpi_thermostat_MON: u32 = 3;

pub const thermostat_mt_dmf_dmf_MON: u32 = 4;

pub const thermostat_mt_mmi_mmi_MON: u32 = 5;

pub const thermostat_mt_mmm_mmm_MON: u32 = 6;

pub const thermostat_mt_ma_ma_MON: u32 = 7;

pub const thermostat_rt_drf_drf_MON: u32 = 8;

pub const thermostat_rt_mri_mri_MON: u32 = 9;

pub const thermostat_rt_mrm_mrm_MON: u32 = 10;

pub const thermostat_rt_mhs_mhs_MON: u32 = 11;

pub const heat_source_cpi_heat_controller_MON: u32 = 12;

pub const sys_nominal_monitor_process_sys_nominal_monitor_thread_MON: u32 = 16;

// For each timeslice index, finds the nearest preceding and following user
// partition channels. This lets the monitor know which thread just yielded
// (prev) and which will run next (next) so it can check post-conditions
// and capture pre-state at the right time.

pub fn buildUserChannelTables(
  sched: &hamr::Schedule,
  prev: &mut hamr::ScheduleChannels,
  next: &mut hamr::ScheduleChannels)
{
  let n = sched.num_timeslices as usize;
  for i in 0..n {
    let mut found_prev = false;
    let mut found_next = false;
    for offset in 1..n {
      if !found_prev {
        let backward = (i + n - offset) % n;
        if sched.is_user_partition[backward] {
          prev[i] = sched.timeslice_ch[backward];
          found_prev = true;
        }
      }
      if !found_next {
        let forward = (i + offset) % n;
        if sched.is_user_partition[forward] {
          next[i] = sched.timeslice_ch[forward];
          found_next = true;
        }
      }
      if found_prev && found_next {
        break;
      }
    }
  }
}

// Maps a schedule channel to the thread it dispatches.  Channel ids belong to this
// variant's system description; the checks in crates/observers identify threads
// by Thread instead.
pub fn thread_of(ch: u32) -> Option<observers::Thread> {
  match ch {
    thermostat_rt_mri_mri_MON => Some(observers::Thread::thermostat_rt_mri_mri),
    thermostat_rt_mhs_mhs_MON => Some(observers::Thread::thermostat_rt_mhs_mhs),
    thermostat_rt_mrm_mrm_MON => Some(observers::Thread::thermostat_rt_mrm_mrm),
    thermostat_rt_drf_drf_MON => Some(observers::Thread::thermostat_rt_drf_drf),
    thermostat_mt_mmi_mmi_MON => Some(observers::Thread::thermostat_mt_mmi_mmi),
    thermostat_mt_ma_ma_MON => Some(observers::Thread::thermostat_mt_ma_ma),
    thermostat_mt_mmm_mmm_MON => Some(observers::Thread::thermostat_mt_mmm_mmm),
    thermostat_mt_dmf_dmf_MON => Some(observers::Thread::thermostat_mt_dmf_dmf),
    operator_interface_oip_oit_MON => Some(observers::Thread::operator_interface_oip_oit),
    temperature_sensor_cpi_thermostat_MON => Some(observers::Thread::temperature_sensor_cpi_thermostat),
    heat_source_cpi_heat_controller_MON => Some(observers::Thread::heat_source_cpi_heat_controller),
    _ => None,
  }
}

